WITH agg AS (SELECT p.p_promo_sk, p.p_promo_name, p.p_channel_tv, SUM(cs.cs_net_profit) AS total_profit, SUM(cr.cr_net_loss) AS total_loss, (SUM(cs.cs_net_profit) - SUM(cr.cr_net_loss)) / NULLIF(SUM(cs.cs_quantity),0) AS profit_per_item, COUNT(DISTINCT cs.cs_order_number) AS orders_count FROM promotion p JOIN catalog_sales cs ON cs.cs_promo_sk = p.p_promo_sk JOIN catalog_returns cr ON cr.cr_order_number = cs.cs_order_number AND cr.cr_item_sk = cs.cs_item_sk WHERE p.p_start_date_sk >= 20000101 AND p.p_end_date_sk <= 20001231 GROUP BY p.p_promo_sk, p.p_promo_name, p.p_channel_tv HAVING COUNT(DISTINCT cs.cs_order_number) >= 50) SELECT agg.p_promo_sk, agg.p_promo_name, agg.p_channel_tv, agg.total_profit, agg.total_loss, agg.profit_per_item, agg.orders_count, RANK() OVER (PARTITION BY agg.p_channel_tv ORDER BY agg.profit_per_item DESC) AS channel_profit_rank FROM agg ORDER BY agg.total_profit DESC LIMIT 8
